export const getDevicesSerialAppliancePerformanceRoute = createRoute({
  method: 'get',
  path: '/devices/{serial}/appliance/performance',
  tags: ['appliance', 'monitor', 'performance'],
  summary: 'Return the performance score for a single Secure Appliance or Secure Router',
  description:
    'Return the performance score for a single Secure Appliance or Secure Router. Only primary Secure Appliance devices supported. If no data is available, a 204 error code is returned.',
  operationId: 'getDeviceAppliancePerformance',
  request: {
    params: z.object({
      serial: z
        .string()
        .openapi({
          param: {
            name: 'serial',
            in: 'path',
            description: 'Serial',
            schema: { type: 'string' },
            required: true,
          },
        }),
    }),
    query: z.object({
      t0: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 't0',
            in: 'query',
            description:
              'The beginning of the timespan for the data. The maximum lookback period is 30 days from today.',
            schema: { type: 'string' },
            required: false,
          },
        }),
      t1: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 't1',
            in: 'query',
            description:
              'The end of the timespan for the data. t1 can be a maximum of 14 days after t0.',
            schema: { type: 'string' },
            required: false,
          },
        }),
      timespan: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.float32().min(1800).max(1209600),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'timespan',
            in: 'query',
            description:
              'The timespan for which the information will be fetched. If specifying timespan, do not specify parameters t0 and t1. The value must be in seconds and be greater than or equal to 30 minutes and be less than or equal to 14 days. The default is 30 minutes.',
            schema: { type: 'number', format: 'float', minimum: 1800, maximum: 1209600 },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successful operation',
      content: {
        'application/json': {
          schema: z
            .object({
              perfScore: z
                .float32()
                .exactOptional()
                .openapi({ description: 'Utilization for the device' }),
            })
            .openapi({ required: [] }),
          example: { perfScore: 10 },
        },
      },
    },
  },
  security: [{ oauth2: ['sdwan:telemetry:read'] }],
})

