export const getDevicesSerialCameraAnalyticsOverviewRoute = createRoute({
  method: 'get',
  path: '/devices/{serial}/camera/analytics/overview',
  tags: ['camera', 'monitor', 'analytics', 'overview'],
  summary: 'Returns an overview of aggregate analytics data for a timespan',
  description: 'Returns an overview of aggregate analytics data for a timespan',
  operationId: 'getDeviceCameraAnalyticsOverview',
  request: {
    params: z.object({
      serial: z
        .string()
        .openapi({
          param: {
            name: 'serial',
            in: 'path',
            description: 'Serial',
            schema: { type: 'string' },
            required: true,
          },
        }),
    }),
    query: z.object({
      t0: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 't0',
            in: 'query',
            description:
              'The beginning of the timespan for the data. The maximum lookback period is 365 days from today.',
            schema: { type: 'string' },
            required: false,
          },
        }),
      t1: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 't1',
            in: 'query',
            description:
              'The end of the timespan for the data. t1 can be a maximum of 7 days after t0.',
            schema: { type: 'string' },
            required: false,
          },
        }),
      timespan: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.float32().max(604800),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'timespan',
            in: 'query',
            description:
              'The timespan for which the information will be fetched. If specifying timespan, do not specify parameters t0 and t1. The value must be in seconds and be less than or equal to 7 days. The default is 1 hour.',
            schema: { type: 'number', format: 'float', maximum: 604800 },
            required: false,
          },
        }),
      objectType: z
        .enum(['person', 'vehicle'])
        .exactOptional()
        .openapi({
          param: {
            name: 'objectType',
            in: 'query',
            description:
              '[optional] The object type for which analytics will be retrieved. The default object type is person. The available types are [person, vehicle].',
            schema: { type: 'string', enum: ['person', 'vehicle'] },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successful operation',
      content: {
        'application/json': {
          schema: z.array(
            z
              .object({
                startTs: z.iso
                  .datetime({ offset: true })
                  .exactOptional()
                  .openapi({ description: 'The start time' }),
                endTs: z.iso
                  .datetime({ offset: true })
                  .exactOptional()
                  .openapi({ description: 'The end time' }),
                zoneId: z.int().exactOptional().openapi({ description: 'The zone id' }),
                entrances: z
                  .int()
                  .exactOptional()
                  .openapi({ description: 'The number of sentrances' }),
                averageCount: z
                  .float32()
                  .exactOptional()
                  .openapi({ description: 'The average count' }),
              })
              .openapi({ required: [] }),
          ),
          example: [
            {
              startTs: '2018-08-15T18:32:38.123Z',
              endTs: '2018-08-15T18:33:38.123Z',
              zoneId: 0,
              entrances: 254,
              averageCount: 5,
            },
          ],
        },
      },
    },
  },
  deprecated: true,
})

