export const getDevicesSerialCellularSimsRoute = createRoute({
  method: 'get',
  path: '/devices/{serial}/cellular/sims',
  tags: ['devices', 'configure', 'cellular', 'sims'],
  summary: 'Return the SIM and APN configurations for a cellular device.',
  description: 'Return the SIM and APN configurations for a cellular device.',
  operationId: 'getDeviceCellularSims',
  request: {
    params: z.object({
      serial: z
        .string()
        .openapi({
          param: {
            name: 'serial',
            in: 'path',
            description: 'Serial',
            schema: { type: 'string' },
            required: true,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successful operation',
      content: {
        'application/json': {
          schema: z
            .object({
              sims: z
                .array(
                  z
                    .object({
                      slot: z
                        .string()
                        .exactOptional()
                        .openapi({
                          description:
                            "SIM slot being configured. Must be 'sim1' on single-sim devices. eSIM slots use the raw slot value for the device, such as 'sim2' or 'sim3'.",
                        }),
                      iccid: z
                        .string()
                        .exactOptional()
                        .openapi({ description: 'Integrated Circuit Card Identification Number' }),
                      imsi: z
                        .string()
                        .exactOptional()
                        .openapi({ description: 'International Mobile Subscriber Identity' }),
                      msisdn: z
                        .string()
                        .exactOptional()
                        .openapi({
                          description: 'Mobile Station Integrated Services Digital Network',
                        }),
                      isPrimary: z
                        .boolean()
                        .default(false)
                        .exactOptional()
                        .openapi({
                          description:
                            "If true, this SIM is activated on platform bootup. It must be true on single-SIM devices and is a required field for dual-SIM MGs unless it is being configured using 'simOrdering'.",
                        }),
                      status: z
                        .enum([
                          'PIN required',
                          'PUK required',
                          'active',
                          'inserted',
                          'not inserted',
                          'standby',
                          'unknown',
                        ])
                        .exactOptional()
                        .openapi({ description: 'Status of the SIM card.' }),
                      apns: z
                        .array(
                          z
                            .object({
                              name: z.string().openapi({ description: 'APN name.' }),
                              allowedIpTypes: z
                                .array(z.string())
                                .openapi({
                                  description:
                                    "IP versions to support (permitted values include 'ipv4', 'ipv6').",
                                }),
                              authentication: z
                                .object({
                                  type: z
                                    .enum(['chap', 'none', 'pap'])
                                    .default('none')
                                    .exactOptional()
                                    .openapi({ description: 'APN auth type.' }),
                                  username: z
                                    .string()
                                    .exactOptional()
                                    .openapi({ description: 'APN username, if type is set.' }),
                                  password: z
                                    .string()
                                    .exactOptional()
                                    .openapi({
                                      description:
                                        'APN password, if type is set (if APN password is not supplied, the password is left unchanged).',
                                    }),
                                })
                                .exactOptional()
                                .openapi({
                                  description: 'APN authentication configurations.',
                                  required: [],
                                }),
                            })
                            .openapi({ required: ['name', 'allowedIpTypes'] }),
                        )
                        .default([])
                        .exactOptional()
                        .openapi({
                          description:
                            'APN configurations. If empty, the default APN will be used.',
                        }),
                      ips: z
                        .array(
                          z
                            .object({
                              translation: z
                                .object({
                                  type: z
                                    .literal('464XLAT')
                                    .exactOptional()
                                    .openapi({
                                      description:
                                        "IP translation mechanism. Only '464XLAT' is currently supported.",
                                    }),
                                  status: z
                                    .enum(['active', 'inactive', 'unknown'])
                                    .exactOptional()
                                    .openapi({
                                      description:
                                        'Observed runtime 464XLAT state for this cellular data connection.',
                                    }),
                                })
                                .exactOptional()
                                .openapi({
                                  description:
                                    'IP translation state for this cellular data connection.',
                                  required: [],
                                }),
                            })
                            .openapi({ required: [] }),
                        )
                        .default([])
                        .exactOptional()
                        .openapi({
                          description: 'IP configurations for each cellular data connection.',
                        }),
                    })
                    .openapi({ required: [] }),
                )
                .exactOptional()
                .openapi({
                  description:
                    'List of SIMs. If a SIM was previously configured and not specified in this request, it will remain unchanged.',
                }),
              simOrdering: z
                .array(z.string())
                .exactOptional()
                .openapi({
                  description:
                    "Specifies the ordering of all SIMs for an MG: primary, secondary, and not-in-use (when applicable). It's required for devices with 3 or more SIMs and can be used in place of 'isPrimary' for dual-SIM devices. Use the raw eSIM slot value for the device, such as 'sim2' or 'sim3'. Sim failover will occur only between primary and secondary sim slots.",
                }),
              simFailover: z
                .object({
                  enabled: z
                    .boolean()
                    .exactOptional()
                    .openapi({ description: 'Failover to secondary SIM' }),
                  timeout: z
                    .int()
                    .exactOptional()
                    .openapi({ description: 'Failover timeout in seconds' }),
                })
                .exactOptional()
                .openapi({ description: 'SIM Failover settings.', required: [] }),
            })
            .openapi({ required: [] }),
          example: {
            sims: [
              {
                slot: 'sim1',
                iccid: '123456789',
                imsi: '123456789012345',
                msisdn: '123456789012345',
                isPrimary: false,
                status: 'inserted',
                apns: [
                  {
                    name: 'internet',
                    allowedIpTypes: ['ipv4', 'ipv6'],
                    authentication: { type: 'pap', username: 'milesmeraki', password: 'secret' },
                  },
                ],
                ips: [{ translation: { type: '464XLAT', status: 'active' } }],
              },
            ],
            simOrdering: ['sim1', 'sim2', 'sim3'],
            simFailover: { enabled: true, timeout: 300 },
          },
        },
      },
    },
  },
  security: [{ oauth2: ['sdwan:config:read'] }],
})

