export const getDevicesSerialClientsRoute = createRoute({
  method: 'get',
  path: '/devices/{serial}/clients',
  tags: ['devices', 'monitor', 'clients'],
  summary: 'List the clients of a device, up to a maximum of a month ago',
  description:
    'List the clients of a device, up to a maximum of a month ago. The usage of each client is returned in kilobytes. If the device is a switch, the switchport is returned; otherwise the switchport field is null. Wireless connection metadata reflects the latest available successful association event in the selected period.',
  operationId: 'getDeviceClients',
  request: {
    params: z.object({
      serial: z
        .string()
        .openapi({
          param: {
            name: 'serial',
            in: 'path',
            description: 'Serial',
            schema: { type: 'string' },
            required: true,
          },
        }),
    }),
    query: z.object({
      t0: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 't0',
            in: 'query',
            description:
              'The beginning of the timespan for the data. The maximum lookback period is 31 days from today.',
            schema: { type: 'string' },
            required: false,
          },
        }),
      timespan: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.float32().max(2678400),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'timespan',
            in: 'query',
            description:
              'The timespan for which the information will be fetched. If specifying timespan, do not specify parameter t0. The value must be in seconds and be less than or equal to 31 days. The default is 1 day.',
            schema: { type: 'number', format: 'float', maximum: 2678400 },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successful operation',
      content: {
        'application/json': {
          schema: z.array(
            z
              .object({
                id: z.string().exactOptional().openapi({ description: 'The ID of the client' }),
                mac: z
                  .string()
                  .exactOptional()
                  .openapi({ description: 'The MAC address of the client' }),
                description: z
                  .string()
                  .exactOptional()
                  .openapi({ description: 'Short description of the client' }),
                mdnsName: z
                  .string()
                  .exactOptional()
                  .openapi({ description: "The client's MDNS name" }),
                dhcpHostname: z
                  .string()
                  .exactOptional()
                  .openapi({ description: "The client's DHCP hostname" }),
                user: z.string().exactOptional().openapi({ description: "The client user's name" }),
                ip: z
                  .string()
                  .exactOptional()
                  .openapi({ description: 'The IP address of the client' }),
                vlan: z
                  .string()
                  .exactOptional()
                  .openapi({
                    description: 'The client-assigned name of the VLAN the client is connected to',
                  }),
                namedVlan: z
                  .string()
                  .exactOptional()
                  .openapi({
                    description: 'The owner-assigned name of the VLAN the client is connected to',
                  }),
                switchport: z
                  .string()
                  .exactOptional()
                  .openapi({
                    description:
                      'The name of the switchport with clients on it, if the device is a switch',
                  }),
                adaptivePolicyGroup: z
                  .string()
                  .exactOptional()
                  .openapi({ description: 'A description of the adaptive policy group' }),
                usage: z
                  .object({
                    sent: z
                      .float32()
                      .exactOptional()
                      .openapi({ description: 'Usage sent by the client' }),
                    recv: z
                      .float32()
                      .exactOptional()
                      .openapi({ description: 'Usage received by the client' }),
                  })
                  .exactOptional()
                  .openapi({
                    description: 'Client usage data for sent and received',
                    required: [],
                  }),
              })
              .openapi({ required: [] }),
          ),
          example: [
            {
              id: 'k74272e',
              mac: '22:33:44:55:66:77',
              description: "Miles's phone",
              mdnsName: "Miles's phone",
              dhcpHostname: 'MilesPhone',
              user: 'milesmeraki',
              ip: '1.2.3.4',
              vlan: '100',
              namedVlan: 'My VLAN',
              switchport: 'My switch port',
              adaptivePolicyGroup: '101',
              usage: { sent: 138, recv: 61 },
            },
          ],
        },
      },
    },
  },
  security: [{ oauth2: ['dashboard:general:telemetry:read'] }],
})

