export const getDevicesSerialSwitchPortsStatusesPacketsRoute = createRoute({
  method: 'get',
  path: '/devices/{serial}/switch/ports/statuses/packets',
  tags: ['switch', 'monitor', 'ports', 'statuses', 'packets'],
  summary: 'Return the packet counters for all the ports of a switch',
  description: 'Return the packet counters for all the ports of a switch',
  operationId: 'getDeviceSwitchPortsStatusesPackets',
  request: {
    params: z.object({
      serial: z
        .string()
        .openapi({
          param: {
            name: 'serial',
            in: 'path',
            description: 'Serial',
            schema: { type: 'string' },
            required: true,
          },
        }),
    }),
    query: z.object({
      t0: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 't0',
            in: 'query',
            description:
              'The beginning of the timespan for the data. The value is used only to determine the elapsed duration between t0 and the time of the request; the API snaps that duration to the nearest preset window (5 minutes, 15 minutes, 1 hour, or 1 day).',
            schema: { type: 'string' },
            required: false,
          },
        }),
      timespan: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.float32().max(86400),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'timespan',
            in: 'query',
            description:
              'The timespan for which the information will be fetched. If specifying timespan, do not specify t0. The value must be in seconds and be less than or equal to 86400 seconds (1 day). The default is 1 day.',
            schema: { type: 'number', format: 'float', maximum: 86400 },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successful operation',
      content: {
        'application/json': {
          schema: z.array(
            z
              .object({
                portId: z
                  .string()
                  .exactOptional()
                  .openapi({
                    description:
                      'The string identifier of this port on the switch. This is commonly just the port number but may contain additional identifying information such as the slot and module-type if the port is located on a port module.',
                  }),
                packets: z
                  .array(
                    z
                      .object({
                        desc: z
                          .string()
                          .exactOptional()
                          .openapi({ description: 'The type of packets being counted.' }),
                        total: z
                          .int()
                          .exactOptional()
                          .openapi({
                            description: 'The total count of sent and received packets.',
                          }),
                        sent: z
                          .int()
                          .exactOptional()
                          .openapi({
                            description:
                              'The total count of packets sent by the switch during the timespan.',
                          }),
                        recv: z
                          .int()
                          .exactOptional()
                          .openapi({
                            description:
                              'The total count of packets received by the switch during the timespan.',
                          }),
                        ratePerSec: z
                          .object({
                            total: z
                              .int()
                              .exactOptional()
                              .openapi({
                                description:
                                  'The rate of all packets sent and received during the timespan',
                              }),
                            sent: z
                              .int()
                              .exactOptional()
                              .openapi({
                                description: 'The rate of packets sent during the timespan',
                              }),
                            recv: z
                              .int()
                              .exactOptional()
                              .openapi({
                                description: 'The rate of packets received during the timespan',
                              }),
                          })
                          .exactOptional()
                          .openapi({
                            description: 'Packet rates measured in packets per second.',
                            required: [],
                          }),
                      })
                      .openapi({ required: [] }),
                  )
                  .exactOptional()
                  .openapi({
                    description:
                      'The packet counts on the switch. Note that this data is collected periodically from the switch. Any data from the past five minutes may be incomplete.',
                  }),
              })
              .openapi({ required: [] }),
          ),
          example: [
            {
              portId: '1',
              packets: [
                {
                  desc: 'Total',
                  total: 112081,
                  sent: 104135,
                  recv: 7946,
                  ratePerSec: { total: 1, sent: 1, recv: 0 },
                },
              ],
            },
          ],
        },
      },
    },
  },
  security: [{ oauth2: ['switch:telemetry:read'] }],
})

