export const getNetworksNetworkIdApplianceFirewallL7FirewallRulesRoute = createRoute({
  method: 'get',
  path: '/networks/{networkId}/appliance/firewall/l7FirewallRules',
  tags: ['appliance', 'configure', 'firewall', 'l7FirewallRules'],
  summary: 'List the MX L7 firewall rules for an MX network',
  description: 'List the MX L7 firewall rules for an MX network',
  operationId: 'getNetworkApplianceFirewallL7FirewallRules',
  request: {
    params: z.object({
      networkId: z
        .string()
        .openapi({
          param: {
            name: 'networkId',
            in: 'path',
            description: 'Network ID',
            schema: { type: 'string' },
            required: true,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successful operation',
      content: {
        'application/json': {
          schema: z
            .object({
              rules: z
                .array(
                  z
                    .object({
                      policy: z
                        .literal('deny')
                        .exactOptional()
                        .openapi({ description: "'Deny' traffic specified by this rule" }),
                      type: z
                        .enum([
                          'allowedCountries',
                          'application',
                          'applicationCategory',
                          'blacklistedCountries',
                          'blockedCountries',
                          'host',
                          'ipRange',
                          'port',
                          'whitelistedCountries',
                        ])
                        .exactOptional()
                        .openapi({
                          description:
                            "Type of the L7 rule. One of: 'application', 'applicationCategory', 'host', 'port', 'ipRange' Country variants accepted: 'allowedCountries'/'blockedCountries' (and backward-compatible 'whitelistedCountries'/'blacklistedCountries').",
                        }),
                      value: z
                        .string()
                        .exactOptional()
                        .openapi({
                          description:
                            "The 'value' of what you want to block. Format of 'value' varies depending on type of the rule. The application categories and application ids can be retrieved from the the 'MX L7 application categories' endpoint. The countries follow the two-letter ISO 3166-1 alpha-2 format.",
                        }),
                    })
                    .openapi({ required: [] }),
                )
                .exactOptional()
                .openapi({
                  description:
                    "An ordered array of the MX L7 firewall rules. Each rule is an object with 'policy', 'type', and 'value'. The 'value' shape depends on 'type': object for application/applicationCategory, string for host/port/ipRange, and an array of 2-letter ISO 3166-1 alpha-2 country codes for allowedCountries/blockedCountries. For backward compatibility, request types also accept whitelistedCountries/blacklistedCountries.",
                }),
            })
            .openapi({ required: [] }),
          example: { rules: [{ policy: 'deny', type: 'host', value: 'google.com' }] },
        },
      },
    },
  },
  security: [{ oauth2: ['sdwan:config:read'] }],
})

