export const getNetworksNetworkIdApplianceTrafficShapingRulesRoute = createRoute({
  method: 'get',
  path: '/networks/{networkId}/appliance/trafficShaping/rules',
  tags: ['appliance', 'configure', 'trafficShaping', 'rules'],
  summary:
    'Display the traffic shaping settings rules for a Security Appliance or Secure Router network',
  description:
    'Display the traffic shaping settings rules for a Security Appliance or Secure Router network',
  operationId: 'getNetworkApplianceTrafficShapingRules',
  request: {
    params: z.object({
      networkId: z
        .string()
        .openapi({
          param: {
            name: 'networkId',
            in: 'path',
            description: 'Network ID',
            schema: { type: 'string' },
            required: true,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successful operation',
      content: {
        'application/json': {
          schema: z
            .object({
              defaultRulesEnabled: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    "Whether default traffic shaping rules are enabled (true) or disabled (false). There are 4 default rules, which can be seen on your network's traffic shaping page. Note that default rules count against the rule limit of 8.",
                }),
              rules: z
                .array(
                  z
                    .object({
                      definitions: z
                        .array(
                          z
                            .object({
                              type: z
                                .enum([
                                  'application',
                                  'applicationCategory',
                                  'destination',
                                  'destination_port',
                                  'host',
                                  'ipRange',
                                  'localNet',
                                  'port',
                                  'source',
                                  'source_port',
                                ])
                                .openapi({
                                  description:
                                    "    The type of definition. Can be one of 'application', 'applicationCategory', 'host', 'port', 'ipRange', 'localNet', 'source', 'source_port', 'destination' or 'destination_port'.\n    Security Appliance networks support 'host', 'port', 'ipRange', 'localNet', 'application', and 'applicationCategory'.\n    Secure Router networks support 'source', 'source_port', 'destination', 'destination_port', 'application', and 'applicationCategory'.\n",
                                }),
                              value: z
                                .string()
                                .openapi({
                                  description:
                                    '    If "type" is \'host\', \'port\', \'ipRange\' or \'localNet\', then "value" must be a string, matching either\n    a hostname (e.g. "somesite.com"), a port (e.g. 8080), or an IP range ("192.1.0.0",\n    "192.1.0.0/16", or "10.1.0.0/16:80"). \'localNet\' also supports CIDR notation, excluding\n    custom ports.\n    If "type" is \'source\', \'source_port\', \'destination\' or \'destination_port\', then "value" must be a string:\n    for \'source\' and \'destination\', the string must be an IPv4 address or CIDR with optional port\n    information (e.g. "192.1.0.0", "192.1.0.0/16", "10.1.0.0/16:80", "10.1.0.0/16:80-90");\n    for \'source_port\' and \'destination_port\', the string must be a single port or port range (e.g. 8080, 8000-9000).\n    If "type" is \'application\' or \'applicationCategory\', then "value" must be an object\n    with the structure { "id": "meraki:layer7/..." }, where "id" is the application category or\n    application ID (for a list of IDs for your network, use the trafficShaping/applicationCategories\n    endpoint).\n',
                                }),
                            })
                            .openapi({ required: ['type', 'value'] }),
                        )
                        .openapi({
                          description:
                            '    A list of objects describing the definitions of your traffic shaping rule. At least one definition is required.\n',
                        }),
                      perClientBandwidthLimits: z
                        .object({
                          settings: z
                            .enum(['custom', 'ignore', 'network default'])
                            .exactOptional()
                            .openapi({
                              description:
                                "    How bandwidth limits are applied by your rule. Can be one of 'network default', 'ignore' or 'custom'.\n    Secure Router networks support only the 'ignore' setting.\n",
                            }),
                          bandwidthLimits: z
                            .object({
                              limitUp: z
                                .int()
                                .exactOptional()
                                .openapi({
                                  description: 'The maximum upload limit (integer, in Kbps).',
                                }),
                              limitDown: z
                                .int()
                                .exactOptional()
                                .openapi({
                                  description: 'The maximum download limit (integer, in Kbps).',
                                }),
                            })
                            .exactOptional()
                            .openapi({
                              description:
                                "The bandwidth limits object, specifying the upload ('limitUp') and download ('limitDown') speed in Kbps. These are only enforced if 'settings' is set to 'custom'.",
                              required: [],
                            }),
                        })
                        .exactOptional()
                        .openapi({
                          description:
                            '    An object describing the bandwidth settings for your rule.\n',
                          required: [],
                        }),
                      dscpTagValue: z
                        .int()
                        .nullable()
                        .exactOptional()
                        .openapi({
                          description:
                            "    The DSCP tag applied by your rule. null means 'Do not change DSCP tag'.\n    For a list of possible tag values, use the trafficShaping/dscpTaggingOptions endpoint.\n",
                        }),
                      priority: z
                        .string()
                        .exactOptional()
                        .openapi({
                          description:
                            "    A string, indicating the priority level for packets bound to your rule.\n    Can be 'low', 'normal' or 'high'. This field is supported for Security Appliance networks.\n",
                        }),
                    })
                    .openapi({ required: ['definitions'] }),
                )
                .exactOptional()
                .openapi({
                  description:
                    '    An array of traffic shaping rules. Rules are applied in the order that\n    they are specified in. An empty list (or null) means no rules. Note that\n    you are allowed a maximum of 8 rules.\n',
                }),
            })
            .openapi({ required: [] }),
          example: {
            defaultRulesEnabled: true,
            rules: [
              {
                definitions: [{ type: 'host', value: 'google.com' }],
                perClientBandwidthLimits: {
                  settings: 'custom',
                  bandwidthLimits: { limitUp: 1000000, limitDown: 1000000 },
                },
                dscpTagValue: 0,
                priority: 'normal',
              },
            ],
          },
        },
      },
    },
  },
  security: [{ oauth2: ['sdwan:config:read'] }],
})

