export const getNetworksNetworkIdClientsClientIdSplashAuthorizationStatusRoute = createRoute({
  method: 'get',
  path: '/networks/{networkId}/clients/{clientId}/splashAuthorizationStatus',
  tags: ['networks', 'configure', 'clients', 'splashAuthorizationStatus'],
  summary:
    "Return the splash authorization for a client, for each SSID they've associated with through splash",
  description:
    "Return the splash authorization for a client, for each SSID they've associated with through splash. Only enabled SSIDs with Click-through splash enabled will be included. Clients can be identified by a client key or either the MAC or IP depending on whether the network uses Track-by-IP.",
  operationId: 'getNetworkClientSplashAuthorizationStatus',
  request: {
    params: z.object({
      networkId: z
        .string()
        .openapi({
          param: {
            name: 'networkId',
            in: 'path',
            description: 'Network ID',
            schema: { type: 'string' },
            required: true,
          },
        }),
      clientId: z
        .string()
        .openapi({
          param: {
            name: 'clientId',
            in: 'path',
            description: 'Client ID',
            schema: { type: 'string' },
            required: true,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successful operation',
      content: {
        'application/json': {
          schema: z
            .object({
              ssids: z
                .object({
                  '0': z
                    .object({
                      isAuthorized: z
                        .boolean()
                        .exactOptional()
                        .openapi({
                          description: 'Whether the client is currently authorized on this SSID',
                        }),
                      authorizedAt: z
                        .string()
                        .nullable()
                        .exactOptional()
                        .openapi({
                          description:
                            'When the client was authorized on this SSID in ISO 8601 format. This field will be null if the client is not currently authorized.',
                        }),
                      expiresAt: z
                        .string()
                        .nullable()
                        .exactOptional()
                        .openapi({
                          description:
                            "When the client's authorization on this SSID expires in ISO 8601 format. This field will be null if the client is not currently authorized or if there is no expiration time for the authorization.",
                        }),
                    })
                    .exactOptional()
                    .openapi({ description: 'Splash authorization for SSID 0', required: [] }),
                })
                .exactOptional()
                .openapi({
                  description:
                    "A map of SSID number to the client's splash authorization status for that SSID. Only SSIDs that the client has connected to in the past will be included.",
                  required: [],
                }),
            })
            .openapi({ required: [] }),
          example: {
            ssids: {
              '0': {
                isAuthorized: true,
                authorizedAt: '2018-05-12T00:00:00Z',
                expiresAt: '2018-05-12T01:00:00Z',
              },
            },
          },
        },
      },
    },
  },
  security: [{ oauth2: ['dashboard:general:config:read'] }],
})

