export const deleteNetworksNetworkIdGroupPoliciesGroupPolicyIdRoute = createRoute({
  method: 'delete',
  path: '/networks/{networkId}/groupPolicies/{groupPolicyId}',
  tags: ['networks', 'configure', 'groupPolicies'],
  summary: 'Delete a group policy',
  description: 'Delete a group policy',
  operationId: 'deleteNetworkGroupPolicy',
  request: {
    params: z.object({
      networkId: z
        .string()
        .openapi({
          param: {
            name: 'networkId',
            in: 'path',
            description: 'Network ID',
            schema: { type: 'string' },
            required: true,
          },
        }),
      groupPolicyId: z
        .string()
        .openapi({
          param: {
            name: 'groupPolicyId',
            in: 'path',
            description: 'Group policy ID',
            schema: { type: 'string' },
            required: true,
          },
        }),
    }),
    query: z.object({
      force: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            'x-release-stage': 'general_availability',
            name: 'force',
            in: 'query',
            description:
              'If true, the system deletes the GP even if there are active clients using the GP. After deletion, active clients that were assigned to that Group Policy will be left without any policy applied. Default is false.',
            schema: { type: 'boolean' },
            required: false,
          },
        }),
    }),
  },
  responses: { 204: { description: 'Successful operation' } },
  security: [{ oauth2: ['dashboard:general:config:write'] }],
})

