export const getNetworksNetworkIdSensorRelationshipsRoute = createRoute({
  method: 'get',
  path: '/networks/{networkId}/sensor/relationships',
  tags: ['sensor', 'configure', 'relationships'],
  summary: 'List the sensor roles for devices in a given network',
  description: 'List the sensor roles for devices in a given network',
  operationId: 'getNetworkSensorRelationships',
  request: {
    params: z.object({
      networkId: z
        .string()
        .openapi({
          param: {
            name: 'networkId',
            in: 'path',
            description: 'Network ID',
            schema: { type: 'string' },
            required: true,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successful operation',
      content: {
        'application/json': {
          schema: z.array(
            z
              .object({
                device: z
                  .object({
                    name: z
                      .string()
                      .exactOptional()
                      .openapi({ description: 'The name of the device' }),
                    serial: z
                      .string()
                      .exactOptional()
                      .openapi({ description: 'The serial of the device' }),
                    productType: z
                      .enum(['camera', 'sensor'])
                      .exactOptional()
                      .openapi({ description: 'The product type of the device' }),
                  })
                  .exactOptional()
                  .openapi({
                    description: 'A sensor or gateway device in the network',
                    required: [],
                  }),
                relationships: z
                  .object({
                    livestream: z
                      .object({
                        relatedDevices: z
                          .array(
                            z
                              .object({
                                serial: z
                                  .string()
                                  .exactOptional()
                                  .openapi({ description: 'The serial of the related device' }),
                                productType: z
                                  .enum(['camera', 'sensor'])
                                  .exactOptional()
                                  .openapi({
                                    description: 'The product type of the related device',
                                  }),
                              })
                              .openapi({ required: [] }),
                          )
                          .exactOptional()
                          .openapi({ description: 'An array of the related devices for the role' }),
                      })
                      .exactOptional()
                      .openapi({
                        description:
                          "A role defined between an MT sensor and an MV camera that adds the camera's livestream to the sensor's details page. Snapshots from the camera will also appear in alert notifications that the sensor triggers.",
                        required: [],
                      }),
                  })
                  .exactOptional()
                  .openapi({
                    description:
                      'An object describing the relationships defined between the device and other devices',
                    required: [],
                  }),
              })
              .openapi({ required: [] }),
          ),
          example: [
            {
              device: { name: 'My sensor', serial: 'Q234-ABCD-0001', productType: 'sensor' },
              relationships: {
                livestream: {
                  relatedDevices: [{ serial: 'Q234-ABCD-5678', productType: 'camera' }],
                },
              },
            },
          ],
        },
      },
    },
  },
  security: [{ oauth2: ['sensor:config:read'] }],
})

export const getNetworksNetworkIdSettingsRoute = createRoute({
  method: 'get',
  path: '/networks/{networkId}/settings',
  tags: ['networks', 'configure', 'settings'],
  summary: 'Return the settings for a network',
  description: 'Return the settings for a network',
  operationId: 'getNetworkSettings',
  request: {
    params: z.object({
      networkId: z
        .string()
        .openapi({
          param: {
            name: 'networkId',
            in: 'path',
            description: 'Network ID',
            schema: { type: 'string' },
            required: true,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successful operation',
      content: {
        'application/json': {
          schema: z
            .object({
              localStatusPageEnabled: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    "Enables / disables the local device status pages (<a target='_blank' href='http://my.meraki.com/'>my.meraki.com, </a><a target='_blank' href='http://ap.meraki.com/'>ap.meraki.com, </a><a target='_blank' href='http://switch.meraki.com/'>switch.meraki.com, </a><a target='_blank' href='http://wired.meraki.com/'>wired.meraki.com</a>). Optional (defaults to true)",
                }),
              remoteStatusPageEnabled: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    "Enables / disables access to the device status page (<a target='_blank'>http://[device's LAN IP])</a>. Optional. Can only be set if localStatusPageEnabled is set to true",
                }),
              localStatusPage: z
                .object({
                  authentication: z
                    .object({
                      enabled: z
                        .boolean()
                        .exactOptional()
                        .openapi({
                          description:
                            'Enables / disables the authentication on Local Status page(s). Beta: For networks with a Catalyst router, authentication cannot be disabled and must be enabled when localStatusPageEnabled is true.',
                        }),
                      username: z
                        .string()
                        .exactOptional()
                        .openapi({
                          description:
                            "The username used for Local Status Page(s). Setting this to null or empty string will clear the value, allowing you to use the default of 'admin'. Beta: For networks with a Catalyst router, only 'admin' or null is accepted.",
                        }),
                    })
                    .exactOptional()
                    .openapi({
                      description:
                        "A hash of Local Status page(s)' authentication options applied to the Network.",
                      required: [],
                    }),
                })
                .exactOptional()
                .openapi({
                  description:
                    "A hash of Local Status page(s)' authentication options applied to the Network.",
                  required: [],
                }),
              securePort: z
                .object({
                  enabled: z
                    .boolean()
                    .exactOptional()
                    .openapi({
                      description: 'Enables / disables SecureConnect on the network. Optional.',
                    }),
                })
                .exactOptional()
                .openapi({
                  description: 'A hash of SecureConnect options applied to the Network.',
                  required: [],
                }),
              fips: z
                .object({
                  enabled: z
                    .boolean()
                    .exactOptional()
                    .openapi({ description: 'Enables / disables FIPS on the network.' }),
                })
                .exactOptional()
                .openapi({
                  description: 'A hash of FIPS options applied to the Network',
                  required: [],
                }),
              namedVlans: z
                .object({
                  enabled: z
                    .boolean()
                    .openapi({ description: 'Enables / disables Named VLANs on the Network.' }),
                })
                .exactOptional()
                .openapi({
                  required: ['enabled'],
                  description: 'A hash of Named VLANs options applied to the Network.',
                }),
            })
            .openapi({ required: [] }),
          example: {
            localStatusPageEnabled: true,
            remoteStatusPageEnabled: true,
            localStatusPage: { authentication: { enabled: false, username: 'admin' } },
            securePort: { enabled: false },
            fips: { enabled: true },
            namedVlans: { enabled: true },
          },
        },
      },
    },
  },
  security: [{ oauth2: ['dashboard:general:config:read'] }],
})

