export const getNetworksNetworkIdSmDevicesDeviceIdPerformanceHistoryRoute = createRoute({
  method: 'get',
  path: '/networks/{networkId}/sm/devices/{deviceId}/performanceHistory',
  tags: ['sm', 'monitor', 'devices', 'performanceHistory'],
  summary:
    'Return historical records of various Systems Manager client metrics for desktop devices.',
  description:
    'Return historical records of various Systems Manager client metrics for desktop devices.',
  operationId: 'getNetworkSmDevicePerformanceHistory',
  request: {
    params: z.object({
      networkId: z
        .string()
        .openapi({
          param: {
            name: 'networkId',
            in: 'path',
            description: 'Network ID',
            schema: { type: 'string' },
            required: true,
          },
        }),
      deviceId: z
        .string()
        .openapi({
          param: {
            name: 'deviceId',
            in: 'path',
            description: 'Device ID',
            schema: { type: 'string' },
            required: true,
          },
        }),
    }),
    query: z.object({
      perPage: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'perPage',
            in: 'query',
            description:
              'The number of entries per page returned. Acceptable range is 3 - 1000. Default is 1000.',
            schema: { type: 'integer' },
            required: false,
          },
        }),
      startingAfter: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'startingAfter',
            in: 'query',
            description:
              'A token used by the server to indicate the start of the page. Often this is a timestamp or an ID but it is not limited to those. This parameter should not be defined by client applications. The link for the first, last, prev, or next page in the HTTP Link header should define it.',
            schema: { type: 'string' },
            required: false,
          },
        }),
      endingBefore: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'endingBefore',
            in: 'query',
            description:
              'A token used by the server to indicate the end of the page. Often this is a timestamp or an ID but it is not limited to those. This parameter should not be defined by client applications. The link for the first, last, prev, or next page in the HTTP Link header should define it.',
            schema: { type: 'string' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successful operation',
      content: {
        'application/json': {
          schema: z.array(
            z
              .object({
                cpuPercentUsed: z
                  .float32()
                  .exactOptional()
                  .openapi({ description: 'The percentage of CPU used as a decimal format.' }),
                memFree: z
                  .int()
                  .exactOptional()
                  .openapi({ description: 'Memory that is not yet in use by the system.' }),
                memWired: z
                  .int()
                  .exactOptional()
                  .openapi({ description: 'Memory used for core OS functions on the device.' }),
                memActive: z
                  .int()
                  .exactOptional()
                  .openapi({ description: 'The active RAM on the device.' }),
                memInactive: z
                  .int()
                  .exactOptional()
                  .openapi({ description: 'The inactive RAM on the device.' }),
                networkSent: z
                  .int()
                  .exactOptional()
                  .openapi({ description: 'Network bandwith transmitted.' }),
                networkReceived: z
                  .int()
                  .exactOptional()
                  .openapi({ description: 'Network bandwith received.' }),
                swapUsed: z
                  .int()
                  .exactOptional()
                  .openapi({
                    description:
                      'The amount of space being used on the startup disk to swap unused files to and from RAM.',
                  }),
                diskUsage: z
                  .object({
                    c: z
                      .object({
                        used: z
                          .int()
                          .exactOptional()
                          .openapi({ description: 'The used disk space.' }),
                        space: z
                          .int()
                          .exactOptional()
                          .openapi({ description: 'The available disk space.' }),
                      })
                      .exactOptional()
                      .openapi({
                        description: 'An object containing current disk usage details.',
                        required: [],
                      }),
                  })
                  .exactOptional()
                  .openapi({
                    description: 'An object containing disk usage details.',
                    required: [],
                  }),
                ts: z
                  .string()
                  .exactOptional()
                  .openapi({ description: 'The time at which the performance was measured.' }),
              })
              .openapi({ required: [] }),
          ),
          example: [
            {
              cpuPercentUsed: 0.95,
              memFree: 1024,
              memWired: 4096,
              memActive: 1024,
              memInactive: 2048,
              networkSent: 512,
              networkReceived: 512,
              swapUsed: 768,
              diskUsage: { c: { used: 2048, space: 9096 } },
              ts: '2018-05-12T00:00:00Z',
            },
          ],
        },
      },
      headers: z.object({
        Link: z
          .string()
          .exactOptional()
          .openapi({
            description:
              'A comma-separated list of first, last, prev, and next relative links used for subsequent paginated requests.',
            param: { required: false },
          }),
      }),
    },
  },
  security: [{ oauth2: ['sm:telemetry:read'] }],
})

