export const getNetworksNetworkIdSnmpRoute = createRoute({
  method: 'get',
  path: '/networks/{networkId}/snmp',
  tags: ['networks', 'configure', 'snmp'],
  summary: 'Return the SNMP settings for a network',
  description: 'Return the SNMP settings for a network',
  operationId: 'getNetworkSnmp',
  request: {
    params: z.object({
      networkId: z
        .string()
        .openapi({
          param: {
            name: 'networkId',
            in: 'path',
            description: 'Network ID',
            schema: { type: 'string' },
            required: true,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successful operation',
      content: {
        'application/json': {
          schema: z
            .object({
              access: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    "The type of SNMP access. Can be one of 'none' (disabled), 'community' (V1/V2c), or 'users' (V3).",
                }),
              communityString: z
                .string()
                .exactOptional()
                .openapi({ description: "SNMP community string if access is 'community'." }),
              users: z
                .array(
                  z
                    .object({
                      username: z
                        .string()
                        .exactOptional()
                        .openapi({ description: 'The username for the SNMP user.' }),
                      passphrase: z
                        .string()
                        .exactOptional()
                        .openapi({ description: 'The passphrase for the SNMP user.' }),
                    })
                    .openapi({ required: [] }),
                )
                .exactOptional()
                .openapi({ description: "SNMP settings if access is 'users'." }),
              authentication: z
                .object({
                  protocol: z
                    .enum(['SHA-1', 'SHA-256', 'SHA-384', 'SHA-512'])
                    .exactOptional()
                    .openapi({ description: 'The SNMPv3 authentication protocol.' }),
                })
                .exactOptional()
                .openapi({
                  description:
                    "SNMPv3 authentication settings. Applicable only if 'access' is 'users'.",
                  required: [],
                }),
              privacy: z
                .object({
                  protocol: z
                    .enum(['AES-128', 'DES'])
                    .exactOptional()
                    .openapi({ description: 'The SNMPv3 privacy protocol.' }),
                })
                .exactOptional()
                .openapi({
                  description: "SNMPv3 privacy settings. Applicable only if 'access' is 'users'.",
                  required: [],
                }),
            })
            .openapi({ required: [] }),
          example: {
            access: 'users',
            communityString: 'sample',
            users: [{ username: 'AzureDiamond', passphrase: 'hunter2' }],
            authentication: { protocol: 'SHA-1' },
            privacy: { protocol: 'AES-128' },
          },
        },
      },
    },
  },
  security: [{ oauth2: ['dashboard:general:telemetry:read'] }],
})

