export const getNetworksNetworkIdTrafficRoute = createRoute({
  method: 'get',
  path: '/networks/{networkId}/traffic',
  tags: ['networks', 'monitor', 'traffic'],
  summary: 'Return the traffic analysis data for this network',
  description:
    'Return the traffic analysis data for this network. Traffic analysis with hostname visibility must be enabled on the network.',
  operationId: 'getNetworkTraffic',
  request: {
    params: z.object({
      networkId: z
        .string()
        .openapi({
          param: {
            name: 'networkId',
            in: 'path',
            description: 'Network ID',
            schema: { type: 'string' },
            required: true,
          },
        }),
    }),
    query: z.object({
      t0: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 't0',
            in: 'query',
            description:
              'The beginning of the timespan for the data. The maximum lookback period is 30 days from today.',
            schema: { type: 'string' },
            required: false,
          },
        }),
      timespan: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.float32().max(2592000),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'timespan',
            in: 'query',
            description:
              'The timespan for which the information will be fetched. If specifying timespan, do not specify parameter t0. The value must be in seconds and be less than or equal to 30 days.',
            schema: { type: 'number', format: 'float', maximum: 2592000 },
            required: false,
          },
        }),
      deviceType: z
        .enum(['appliance', 'combined', 'switch', 'wireless'])
        .exactOptional()
        .openapi({
          param: {
            name: 'deviceType',
            in: 'query',
            description:
              "Filter the data by device type: 'combined', 'wireless', 'switch' or 'appliance'. Defaults to 'combined'. When using 'combined', for each rule the data will come from the device type with the most usage.",
            schema: { type: 'string', enum: ['appliance', 'combined', 'switch', 'wireless'] },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successful operation',
      content: {
        'application/json': {
          schema: z.array(
            z
              .object({
                application: z
                  .string()
                  .exactOptional()
                  .openapi({ description: 'Traffic application' }),
                destination: z
                  .string()
                  .exactOptional()
                  .openapi({ description: 'Traffic destination' }),
                protocol: z.string().exactOptional().openapi({ description: 'Traffic protocol' }),
                port: z.int().exactOptional().openapi({ description: 'Traffic port' }),
                sent: z.float32().exactOptional().openapi({ description: 'Traffic sent in kb' }),
                recv: z
                  .float32()
                  .exactOptional()
                  .openapi({ description: 'Traffic received in kb' }),
                numClients: z
                  .int()
                  .exactOptional()
                  .openapi({ description: 'Number of clients with traffic' }),
                activeTime: z
                  .int()
                  .exactOptional()
                  .openapi({ description: 'Active time with traffic' }),
                flows: z.int().exactOptional().openapi({ description: 'Number of traffic flows' }),
              })
              .openapi({ required: [] }),
          ),
          example: [
            {
              application: 'Gmail',
              destination: '2.3.4.5',
              protocol: 'TCP',
              port: 443,
              sent: 138,
              recv: 61,
              numClients: 7,
              activeTime: 77000,
              flows: 300,
            },
          ],
        },
      },
    },
  },
  security: [{ oauth2: ['dashboard:general:telemetry:read'] }],
})

export const getNetworksNetworkIdTrafficAnalysisRoute = createRoute({
  method: 'get',
  path: '/networks/{networkId}/trafficAnalysis',
  tags: ['networks', 'configure', 'trafficAnalysis'],
  summary: 'Return the traffic analysis settings for a network',
  description: 'Return the traffic analysis settings for a network',
  operationId: 'getNetworkTrafficAnalysis',
  request: {
    params: z.object({
      networkId: z
        .string()
        .openapi({
          param: {
            name: 'networkId',
            in: 'path',
            description: 'Network ID',
            schema: { type: 'string' },
            required: true,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successful operation',
      content: {
        'application/json': {
          schema: z
            .object({
              mode: z
                .enum(['basic', 'detailed', 'disabled'])
                .exactOptional()
                .openapi({
                  description:
                    "    The traffic analysis mode for the network. Can be one of 'disabled' (do not collect traffic types),\n    'basic' (collect generic traffic categories), or 'detailed' (collect destination hostnames).\n",
                }),
              customPieChartItems: z
                .array(
                  z
                    .object({
                      name: z
                        .string()
                        .openapi({ description: 'The name of the custom pie chart item.' }),
                      type: z
                        .enum(['host', 'ipRange', 'port'])
                        .openapi({
                          description:
                            "    The signature type for the custom pie chart item. Can be one of 'host', 'port' or 'ipRange'.\n",
                        }),
                      value: z
                        .string()
                        .openapi({
                          description:
                            '    The value of the custom pie chart item. Valid syntax depends on the signature type of the chart item\n    (see sample request/response for more details).\n',
                        }),
                    })
                    .openapi({ required: ['name', 'type', 'value'] }),
                )
                .exactOptional()
                .openapi({
                  description:
                    'The list of items that make up the custom pie chart for traffic reporting.',
                }),
            })
            .openapi({ required: [] }),
          example: {
            mode: 'disabled',
            customPieChartItems: [
              { name: 'Item from hostname', type: 'host', value: 'example.com' },
            ],
          },
        },
      },
    },
  },
  security: [{ oauth2: ['sdwan:config:read'] }],
})

