export const getNetworksNetworkIdWirelessAirMarshalRoute = createRoute({
  method: 'get',
  path: '/networks/{networkId}/wireless/airMarshal',
  tags: ['wireless', 'monitor', 'airMarshal'],
  summary: 'List Air Marshal scan results from a network',
  description: 'List Air Marshal scan results from a network',
  operationId: 'getNetworkWirelessAirMarshal',
  request: {
    params: z.object({
      networkId: z
        .string()
        .openapi({
          param: {
            name: 'networkId',
            in: 'path',
            description: 'Network ID',
            schema: { type: 'string' },
            required: true,
          },
        }),
    }),
    query: z.object({
      t0: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 't0',
            in: 'query',
            description:
              'The beginning of the timespan for the data. The maximum lookback period is 31 days from today.',
            schema: { type: 'string' },
            required: false,
          },
        }),
      timespan: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.float32().max(2678400),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'timespan',
            in: 'query',
            description:
              'The timespan for which the information will be fetched. If specifying timespan, do not specify parameter t0. The value must be in seconds and be less than or equal to 31 days. The default is 7 days.',
            schema: { type: 'number', format: 'float', maximum: 2678400 },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successful operation',
      content: {
        'application/json': {
          schema: z.array(
            z
              .object({
                ssid: z.string().exactOptional().openapi({ description: 'SSID name' }),
                bssids: z
                  .array(
                    z
                      .object({
                        bssid: z
                          .string()
                          .exactOptional()
                          .openapi({ description: 'BSSID of the observed SSID' }),
                        contained: z
                          .boolean()
                          .exactOptional()
                          .openapi({ description: 'Whether this BSSID is contained' }),
                        detectedBy: z
                          .array(
                            z
                              .object({
                                device: z
                                  .string()
                                  .exactOptional()
                                  .openapi({ description: 'Serial of the detecting AP' }),
                                rssi: z
                                  .int()
                                  .exactOptional()
                                  .openapi({ description: 'RSSI reported by the AP' }),
                              })
                              .openapi({ required: [] }),
                          )
                          .exactOptional()
                          .openapi({ description: 'Access points that detected the BSSID' }),
                      })
                      .openapi({ required: [] }),
                  )
                  .exactOptional()
                  .openapi({ description: 'BSSIDs broadcasting the SSID' }),
                channels: z
                  .array(z.int())
                  .exactOptional()
                  .openapi({ description: 'Channels where the SSID was observed' }),
                firstSeen: z
                  .int()
                  .exactOptional()
                  .openapi({ description: 'First time the SSID was observed (epoch seconds)' }),
                lastSeen: z
                  .int()
                  .exactOptional()
                  .openapi({
                    description: 'Most recent time the SSID was observed (epoch seconds)',
                  }),
                wiredMacs: z
                  .array(z.string())
                  .exactOptional()
                  .openapi({ description: 'MAC addresses observed on the SSID' }),
                wiredVlans: z
                  .array(z.int())
                  .exactOptional()
                  .openapi({ description: 'VLAN IDs observed on the SSID' }),
                wiredLastSeen: z
                  .int()
                  .exactOptional()
                  .openapi({ description: 'Last time observed on the SSID (epoch seconds)' }),
                manufacturers: z
                  .array(z.string())
                  .exactOptional()
                  .openapi({
                    description:
                      'Vendor names resolved from the OUI of each broadcasting BSSID (not the OUI hex prefix itself). Strings come from the IEEE OUI registry and are not casing-normalized -- callers should compare case-insensitively. Example values: "Linksys", "Cisco Systems", "OMRON TATEISI Electronics". Deduplicated and capped at 10 entries; empty when no OUI can be resolved.',
                  }),
                encryption: z
                  .enum(['WEP', 'WPA', 'open'])
                  .nullable()
                  .exactOptional()
                  .openapi({
                    description:
                      'High-level encryption mode observed for the SSID; null when it cannot be inferred',
                  }),
                types: z
                  .array(z.enum(['rogue', 'spoof']))
                  .exactOptional()
                  .openapi({
                    description:
                      'Threat classifications applied to this SSID. "rogue": seen on LAN and not allow-listed by an is_known containment rule. "spoof": SSID name matches an enabled SSID on this network. Empty when no classification applies.',
                  }),
              })
              .openapi({ required: [] }),
          ),
          example: [
            {
              ssid: 'linksys',
              bssids: [
                {
                  bssid: '00:11:22:33:44:55',
                  contained: false,
                  detectedBy: [{ device: 'Q234-ABCD-5678', rssi: 17 }],
                },
              ],
              channels: [36, 40],
              firstSeen: 1518365681,
              lastSeen: 1526087474,
              wiredMacs: ['00:11:22:33:44:55'],
              wiredVlans: [0, 108],
              wiredLastSeen: 1526087474,
              manufacturers: ['Linksys', 'Cisco Systems'],
              encryption: 'WPA',
              types: ['rogue'],
            },
          ],
        },
      },
    },
  },
  security: [{ oauth2: ['wireless:config:read'] }],
})

