export const getNetworksNetworkIdWirelessSignalQualityHistoryRoute = createRoute({
  method: 'get',
  path: '/networks/{networkId}/wireless/signalQualityHistory',
  tags: ['wireless', 'monitor', 'signalQualityHistory'],
  summary: 'Return signal quality (SNR/RSSI) over time for a device or network client',
  description: 'Return signal quality (SNR/RSSI) over time for a device or network client',
  operationId: 'getNetworkWirelessSignalQualityHistory',
  request: {
    params: z.object({
      networkId: z
        .string()
        .openapi({
          param: {
            name: 'networkId',
            in: 'path',
            description: 'Network ID',
            schema: { type: 'string' },
            required: true,
          },
        }),
    }),
    query: z.object({
      t0: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 't0',
            in: 'query',
            description:
              'The beginning of the timespan for the data. The maximum lookback period is 31 days from today.',
            schema: { type: 'string' },
            required: false,
          },
        }),
      t1: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 't1',
            in: 'query',
            description:
              'The end of the timespan for the data. t1 can be a maximum of 31 days after t0.',
            schema: { type: 'string' },
            required: false,
          },
        }),
      timespan: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.float32().max(2678400),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'timespan',
            in: 'query',
            description:
              'The timespan for which the information will be fetched. If specifying timespan, do not specify parameters t0 and t1. The value must be in seconds and be less than or equal to 31 days. The default is 7 days.',
            schema: { type: 'number', format: 'float', maximum: 2678400 },
            required: false,
          },
        }),
      resolution: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'resolution',
            in: 'query',
            description:
              'The time resolution in seconds for returned data. The valid resolutions are: 300, 600, 1200, 3600, 14400, 86400. The default is 86400.',
            schema: { type: 'integer' },
            required: false,
          },
        }),
      autoResolution: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            name: 'autoResolution',
            in: 'query',
            description:
              "Automatically select a data resolution based on the given timespan; this overrides the value specified by the 'resolution' parameter. The default setting is false.",
            schema: { type: 'boolean' },
            required: false,
          },
        }),
      clientId: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'clientId',
            in: 'query',
            description: 'Filter results by network client.',
            schema: { type: 'string' },
            required: false,
          },
        }),
      deviceSerial: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'deviceSerial',
            in: 'query',
            description: 'Filter results by device.',
            schema: { type: 'string' },
            required: false,
          },
        }),
      apTag: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'apTag',
            in: 'query',
            description:
              'Filter results by AP tag; either :clientId or :deviceSerial must be jointly specified.',
            schema: { type: 'string' },
            required: false,
          },
        }),
      band: z
        .enum(['2.4', '5', '6'])
        .exactOptional()
        .openapi({
          param: {
            name: 'band',
            in: 'query',
            description: "Filter results by band (either '2.4', '5' or '6').",
            schema: { type: 'string', enum: ['2.4', '5', '6'] },
            required: false,
          },
        }),
      ssid: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'ssid',
            in: 'query',
            description: 'Filter results by SSID number.',
            schema: { type: 'integer' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successful operation',
      content: {
        'application/json': {
          schema: z.array(
            z
              .object({
                startTs: z.iso
                  .datetime({ offset: true })
                  .exactOptional()
                  .openapi({ description: 'The start time of the query range' }),
                endTs: z.iso
                  .datetime({ offset: true })
                  .exactOptional()
                  .openapi({ description: 'The end time of the query range' }),
                snr: z.int().exactOptional().openapi({ description: 'Signal to noise ratio' }),
                rssi: z
                  .int()
                  .exactOptional()
                  .openapi({ description: 'Received signal strength indicator' }),
              })
              .openapi({ required: [] }),
          ),
          example: [
            { startTs: '2020-01-01T00:00:00Z', endTs: '2020-01-01T01:00:00Z', snr: 27, rssi: -77 },
          ],
        },
      },
    },
  },
  security: [{ oauth2: ['wireless:telemetry:read'] }],
})

