export const postOrganizationsOrganizationIdAssuranceAlertsDismissRoute = createRoute({
  method: 'post',
  path: '/organizations/{organizationId}/assurance/alerts/dismiss',
  tags: ['organizations', 'monitor', 'alerts'],
  summary: 'Dismiss health alerts',
  description: 'Dismiss health alerts',
  operationId: 'dismissOrganizationAssuranceAlerts',
  request: {
    params: z.object({
      organizationId: z
        .string()
        .openapi({
          param: {
            name: 'organizationId',
            in: 'path',
            description: 'Organization ID',
            schema: { type: 'string' },
            required: true,
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              alertIds: z
                .array(z.string())
                .openapi({
                  description:
                    'Array of alert IDs in this organization to dismiss. Missing or inaccessible alert IDs return 404.',
                }),
            })
            .openapi({ example: { alertIds: ['1234', '4567'] }, required: ['alertIds'] }),
        },
      },
      required: true,
    },
  },
  responses: { 204: { description: 'Successful operation' } },
})

