export const getOrganizationsOrganizationIdDevicesCellularDataUsageByDeviceRoute = createRoute({
  method: 'get',
  path: '/organizations/{organizationId}/devices/cellular/data/usage/byDevice',
  tags: ['organizations', 'monitor', 'devices', 'cellular', 'data', 'usage', 'byDevice'],
  summary: 'List current cellular data usage for devices in this organization',
  description:
    "List current cellular data usage for devices in this organization. Returns a paginated per-device view of current SIM usage in each device's current usage period (as set by the device's configuration). Supports filtering by device serials.",
  operationId: 'getOrganizationDevicesCellularDataUsageByDevice',
  request: {
    params: z.object({
      organizationId: z
        .string()
        .openapi({
          param: {
            name: 'organizationId',
            in: 'path',
            description: 'Organization ID',
            schema: { type: 'string' },
            required: true,
          },
        }),
    }),
    query: z.object({
      serials: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string()).max(1000),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'serials',
            in: 'query',
            description: 'Filter the results by device serials. Maximum 1000 serials.',
            schema: { type: 'array', items: { type: 'string' }, maxItems: 1000 },
            required: false,
          },
        }),
      perPage: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'perPage',
            in: 'query',
            description:
              'The number of entries per page returned. Acceptable range is 3 - 1000. Default is 100.',
            schema: { type: 'integer' },
            required: false,
          },
        }),
      startingAfter: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'startingAfter',
            in: 'query',
            description:
              'A token used by the server to indicate the start of the page. Often this is a timestamp or an ID but it is not limited to those. This parameter should not be defined by client applications. The link for the first, last, prev, or next page in the HTTP Link header should define it.',
            schema: { type: 'string' },
            required: false,
          },
        }),
      endingBefore: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'endingBefore',
            in: 'query',
            description:
              'A token used by the server to indicate the end of the page. Often this is a timestamp or an ID but it is not limited to those. This parameter should not be defined by client applications. The link for the first, last, prev, or next page in the HTTP Link header should define it.',
            schema: { type: 'string' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successful operation',
      content: {
        'application/json': {
          schema: z
            .object({
              items: z
                .array(
                  z
                    .object({
                      serial: z
                        .string()
                        .exactOptional()
                        .openapi({ description: 'Serial of device' }),
                      bySlot: z
                        .array(
                          z
                            .object({
                              slot: z
                                .enum(['esim', 'sim1', 'sim2'])
                                .exactOptional()
                                .openapi({
                                  description:
                                    'Identifier for the logical SIM slot. Accepted values are sim1, sim2, and esim.',
                                }),
                              isActive: z
                                .boolean()
                                .exactOptional()
                                .openapi({
                                  description:
                                    'Whether a SIM is installed in the slot or the eSIM has an active profile.',
                                }),
                              total: z
                                .string()
                                .exactOptional()
                                .openapi({
                                  description:
                                    'Current data usage on the SIM as a string-encoded byte count',
                                }),
                              lastUpdatedAt: z
                                .string()
                                .exactOptional()
                                .openapi({
                                  description:
                                    'Timestamp of when the usage was last reported from the device',
                                }),
                              startTs: z
                                .string()
                                .exactOptional()
                                .openapi({
                                  description: 'Start of the current usage period for the device',
                                }),
                              endTs: z
                                .string()
                                .exactOptional()
                                .openapi({
                                  description: 'End of the current usage period for the device',
                                }),
                              limit: z
                                .string()
                                .exactOptional()
                                .openapi({
                                  description:
                                    'Data limit for the SIM as a string-encoded byte count, if applicable',
                                }),
                            })
                            .openapi({ required: [] }),
                        )
                        .max(3)
                        .exactOptional()
                        .openapi({
                          description:
                            'Information about the supported SIM slots for the device. Maximum 3 entries.',
                        }),
                    })
                    .openapi({ required: [] }),
                )
                .max(1000)
                .exactOptional()
                .openapi({
                  description:
                    'Devices with their current cellular data usage information. Maximum 1000 items per page.',
                }),
              meta: z
                .object({
                  counts: z
                    .object({
                      items: z
                        .object({
                          total: z
                            .int()
                            .exactOptional()
                            .openapi({ description: 'Total number of devices available' }),
                          remaining: z
                            .int()
                            .exactOptional()
                            .openapi({
                              description: 'Remaining number of devices (for paginated response)',
                            }),
                        })
                        .exactOptional()
                        .openapi({ description: 'Count of devices', required: [] }),
                    })
                    .exactOptional()
                    .openapi({ description: 'Count of involved entities', required: [] }),
                })
                .exactOptional()
                .openapi({ description: 'Meta data about the results', required: [] }),
            })
            .openapi({ required: [] }),
          example: {
            items: [
              {
                serial: 'Q234-ABCD-5678',
                bySlot: [
                  {
                    slot: 'esim',
                    isActive: true,
                    total: '12345',
                    lastUpdatedAt: '2024-01-01T12:00:00Z',
                    startTs: '2024-01-01T00:00:00Z',
                    endTs: '2024-01-31T23:59:59Z',
                    limit: '1024',
                  },
                ],
              },
            ],
            meta: { counts: { items: { total: 1, remaining: 0 } } },
          },
        },
      },
      headers: z.object({
        Link: z
          .string()
          .exactOptional()
          .openapi({
            description:
              'A comma-separated list of first, last, prev, and next relative links used for subsequent paginated requests.',
            param: { required: false },
          }),
      }),
    },
  },
})

