export const getOrganizationsOrganizationIdLicensesRoute = createRoute({
  method: 'get',
  path: '/organizations/{organizationId}/licenses',
  tags: ['organizations', 'configure', 'licenses'],
  summary: 'List the licenses for an organization',
  description: 'List the licenses for an organization',
  operationId: 'getOrganizationLicenses',
  request: {
    params: z.object({
      organizationId: z
        .string()
        .openapi({
          param: {
            name: 'organizationId',
            in: 'path',
            description: 'Organization ID',
            schema: { type: 'string' },
            required: true,
          },
        }),
    }),
    query: z.object({
      perPage: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'perPage',
            in: 'query',
            description:
              'The number of entries per page returned. Acceptable range is 3 - 1000. Default is 1000.',
            schema: { type: 'integer' },
            required: false,
          },
        }),
      startingAfter: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'startingAfter',
            in: 'query',
            description:
              'A token used by the server to indicate the start of the page. Often this is a timestamp or an ID but it is not limited to those. This parameter should not be defined by client applications. The link for the first, last, prev, or next page in the HTTP Link header should define it.',
            schema: { type: 'string' },
            required: false,
          },
        }),
      endingBefore: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'endingBefore',
            in: 'query',
            description:
              'A token used by the server to indicate the end of the page. Often this is a timestamp or an ID but it is not limited to those. This parameter should not be defined by client applications. The link for the first, last, prev, or next page in the HTTP Link header should define it.',
            schema: { type: 'string' },
            required: false,
          },
        }),
      deviceSerial: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'deviceSerial',
            in: 'query',
            description:
              'Filter the licenses to those assigned to a particular device. Returned in the same order that they are queued to the device.',
            schema: { type: 'string' },
            required: false,
          },
        }),
      networkId: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'networkId',
            in: 'query',
            description: 'Filter the licenses to those assigned in a particular network',
            schema: { type: 'string' },
            required: false,
          },
        }),
      state: z
        .enum(['active', 'expired', 'expiring', 'recentlyQueued', 'unused', 'unusedActive'])
        .exactOptional()
        .openapi({
          param: {
            name: 'state',
            in: 'query',
            description:
              "Filter the licenses to those in a particular state. Can be one of 'active', 'expired', 'expiring', 'recentlyQueued', 'unused' or 'unusedActive'",
            schema: {
              type: 'string',
              enum: ['active', 'expired', 'expiring', 'recentlyQueued', 'unused', 'unusedActive'],
            },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successful operation',
      content: {
        'application/json': {
          schema: z.array(
            z
              .object({
                id: z.string().exactOptional().openapi({ description: 'License ID' }),
                licenseType: z.string().exactOptional().openapi({ description: 'License type' }),
                licenseKey: z.string().exactOptional().openapi({ description: 'License key' }),
                orderNumber: z.string().exactOptional().openapi({ description: 'Order number' }),
                deviceSerial: z
                  .string()
                  .exactOptional()
                  .openapi({
                    description: 'Serial number of the device the license is assigned to',
                  }),
                networkId: z
                  .string()
                  .exactOptional()
                  .openapi({ description: 'ID of the network the license is assigned to' }),
                state: z
                  .enum([
                    'active',
                    'expired',
                    'expiring',
                    'recentlyQueued',
                    'unused',
                    'unusedActive',
                  ])
                  .exactOptional()
                  .openapi({
                    description:
                      'The state of the license. All queued licenses have a status of `recentlyQueued`.',
                  }),
                seatCount: z
                  .int()
                  .exactOptional()
                  .openapi({
                    description:
                      'The number of seats of the license. Only applicable to SM licenses.',
                  }),
                totalDurationInDays: z
                  .int()
                  .exactOptional()
                  .openapi({
                    description:
                      'The duration of the license plus all permanently queued licenses associated with it',
                  }),
                durationInDays: z
                  .int()
                  .exactOptional()
                  .openapi({ description: 'The duration of the individual license' }),
                permanentlyQueuedLicenses: z
                  .array(
                    z
                      .object({
                        id: z
                          .string()
                          .exactOptional()
                          .openapi({ description: 'Permanently queued license ID' }),
                        licenseType: z
                          .string()
                          .exactOptional()
                          .openapi({ description: 'License type' }),
                        licenseKey: z
                          .string()
                          .exactOptional()
                          .openapi({ description: 'License key' }),
                        orderNumber: z
                          .string()
                          .exactOptional()
                          .openapi({ description: 'Order number' }),
                        durationInDays: z
                          .int()
                          .exactOptional()
                          .openapi({ description: 'The duration of the individual license' }),
                      })
                      .openapi({ required: [] }),
                  )
                  .exactOptional()
                  .openapi({
                    description:
                      'DEPRECATED List of permanently queued licenses attached to the license. Instead, use /organizations/{organizationId}/licenses?deviceSerial= to retrieved queued licenses for a given device.',
                  }),
                claimDate: z
                  .string()
                  .exactOptional()
                  .openapi({
                    description: 'The date the license was claimed into the organization',
                  }),
                activationDate: z
                  .string()
                  .exactOptional()
                  .openapi({ description: 'The date the license started burning' }),
                expirationDate: z
                  .string()
                  .exactOptional()
                  .openapi({ description: 'The date the license will expire' }),
                headLicenseId: z
                  .string()
                  .exactOptional()
                  .openapi({
                    description:
                      'The id of the head license this license is queued behind. If there is no head license, it returns nil.',
                  }),
              })
              .openapi({ required: [] }),
          ),
          example: [
            {
              id: '1234',
              licenseType: 'MX64-ENT',
              licenseKey: 'Z21234567890',
              orderNumber: '4C1234567',
              deviceSerial: 'Q234-ABCD-5678',
              networkId: 'N_24329156',
              state: 'active',
              seatCount: 25,
              totalDurationInDays: 425,
              durationInDays: 365,
              permanentlyQueuedLicenses: [
                {
                  id: '1234',
                  licenseType: 'MX64-ENT',
                  licenseKey: 'Z21234567890',
                  orderNumber: '4C1234567',
                  durationInDays: 60,
                },
              ],
              claimDate: '2019-08-29T12:40:10Z',
              activationDate: '2019-09-01T15:01:46Z',
              expirationDate: '2020-10-30T15:01:46Z',
              headLicenseId: '1234',
            },
          ],
        },
      },
      headers: z.object({
        Link: z
          .string()
          .exactOptional()
          .openapi({
            description:
              'A comma-separated list of first, last, prev, and next relative links used for subsequent paginated requests.',
            param: { required: false },
          }),
      }),
    },
  },
  security: [{ oauth2: ['dashboard:licensing:config:read'] }],
})

